UPDATE
	UNTACT_BOOK_RESERVATION
SET
	locker_password = #{locker_password}
WHERE
	homepage_id = #{homepage_id}
AND request_number = #{request_number}
AND cancel_yn = 'N'
AND round_idx = (SELECT
					round_idx
				FROM
					UNTACT_BOOK_ROUND
				WHERE
					homepage_id = #{homepage_id}
				AND round_end_date = (SELECT
											round_start_date
										FROM
											UNTACT_BOOK_ROUND
										WHERE 1=1		
										AND homepage_id = #{homepage_id}
										AND round_idx = #{round_idx}
									  )
		         )

UPDATE
	UNTACT_BOOK_RESERVATION
SET
	reservation_step = #{reservation_step}
WHERE
	homepage_id = #{homepage_id}
AND request_number IN

